import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-DCZUiBeJ.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/MySQL/01_%E5%9F%BA%E7%A1%80%E7%AF%87/03_%E7%B4%A2%E5%BC%95%E5%8E%9F%E7%90%86.html","title":"索引原理","lang":"zh-CN","frontmatter":{"title":"索引原理","icon":"fa6-brands:mysql","order":3,"category":["数据库","MySQL"],"tag":["MySQL","B+树","索引","InnoDB","覆盖索引"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":11.14,"words":3343},"filePathRelative":"后端开发/数据库/MySQL/01_基础篇/03_索引原理.md"}`),s={name:`03_索引原理.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="索引原理" tabindex="-1"><a class="header-anchor" href="#索引原理"><span>索引原理</span></a></h1><p>索引是 MySQL 性能调优的核心。理解 B+ 树结构、聚簇索引与二级索引的区别、索引下推与覆盖索引等机制，才能在面试和实战中设计出高效的索引方案。</p><h2 id="_1-b-树结构" tabindex="-1"><a class="header-anchor" href="#_1-b-树结构"><span>1. B+ 树结构</span></a></h2><h3 id="_1-1-为什么选择-b-树" tabindex="-1"><a class="header-anchor" href="#_1-1-为什么选择-b-树"><span>1.1 为什么选择 B+ 树</span></a></h3><table><thead><tr><th>结构</th><th>磁盘 IO 次数</th><th>范围查询</th><th>数据位置</th></tr></thead><tbody><tr><td>二叉搜索树</td><td>O(logN) 但树太高</td><td>需中序遍历</td><td>节点内</td></tr><tr><td>Hash 索引</td><td>O(1)</td><td>❌ 不支持</td><td>桶内</td></tr><tr><td>B 树</td><td>O(logN)</td><td>需中序遍历</td><td><strong>所有节点</strong></td></tr><tr><td>B+ 树</td><td>O(logN) 更矮</td><td>✅ 叶子链表</td><td><strong>仅叶子节点</strong></td></tr></tbody></table><p>B+ 树的优势：</p><ul><li><strong>非叶子节点只存键值</strong>，单个页能容纳更多键，树更矮，IO 更少</li><li><strong>叶子节点链表</strong>，范围查询只需顺序扫描</li><li><strong>数据只存叶子</strong>，查询路径长度一致，性能稳定</li></ul><h3 id="_1-2-b-树三层结构示意" tabindex="-1"><a class="header-anchor" href="#_1-2-b-树三层结构示意"><span>1.2 B+ 树三层结构示意</span></a></h3>`,8),i(d,{code:``}),o[1]||=n(`<div class="hint-container tip"><p class="hint-container-title">B+ 树能存多少行？</p><p>InnoDB 默认页大小 16KB。假设主键 BIGINT（8 字节）+ 指针（6 字节）= 14 字节/键：</p><ul><li><strong>非叶子节点</strong>：16KB / 14B ≈ 1170 个键</li><li><strong>叶子节点</strong>：假设行 1KB，16KB / 1KB ≈ 16 行</li><li><strong>三层 B+ 树</strong>：1170 × 1170 × 16 ≈ <strong>2190 万行</strong></li><li>只需 3 次 IO 即可从 2000 万行中找到任意一行！</li></ul></div><h2 id="_2-聚簇索引-vs-二级索引" tabindex="-1"><a class="header-anchor" href="#_2-聚簇索引-vs-二级索引"><span>2. 聚簇索引 vs 二级索引</span></a></h2><h3 id="_2-1-聚簇索引-clustered-index" tabindex="-1"><a class="header-anchor" href="#_2-1-聚簇索引-clustered-index"><span>2.1 聚簇索引（Clustered Index）</span></a></h3><p>InnoDB 的聚簇索引就是<strong>主键索引</strong>，叶子节点存储<strong>完整的行数据</strong>。一张表只有一个聚簇索引。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> employees</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id         </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">       VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">64</span><span style="color:#ABB2BF;">)  </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    dept_id    </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    salary     </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    hire_date  </span><span style="color:#C678DD;">DATE</span><span style="color:#C678DD;">         NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_dept (dept_id),</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_name_salary (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, salary)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 聚簇索引结构：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 叶子节点按 id 顺序存储完整行：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- [1|张三|10|15000|2023-01-15] → [2|李四|20|18000|2023-03-20] → ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-二级索引-secondary-index" tabindex="-1"><a class="header-anchor" href="#_2-2-二级索引-secondary-index"><span>2.2 二级索引（Secondary Index）</span></a></h3><p>二级索引的叶子节点存储<strong>主键值</strong>，不是完整行数据。查询非索引列需要<strong>回表</strong>。</p>`,7),i(d,{code:``}),o[2]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 通过二级索引查询需要回表</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行过程：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 在 idx_dept 中找到 dept_id=10 的所有主键: [1, 5]</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 用主键回到聚簇索引查找完整行（回表 2 次）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 只查主键和索引列，不需要回表（覆盖索引）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, dept_id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行过程：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 在 idx_dept 中找到 dept_id=10 的记录</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 叶子节点已有 id 和 dept_id，无需回表 ✅</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-为什么推荐自增主键" tabindex="-1"><a class="header-anchor" href="#_2-3-为什么推荐自增主键"><span>2.3 为什么推荐自增主键</span></a></h3><table><thead><tr><th>主键类型</th><th>页分裂</th><th>空间碎片</th><th>二级索引体积</th></tr></thead><tbody><tr><td>自增 INT/BIGINT</td><td>无（顺序追加）</td><td>无</td><td>小（4/8 字节）</td></tr><tr><td>UUID / 随机字符串</td><td><strong>频繁分裂</strong></td><td><strong>大量碎片</strong></td><td>大（36 字节）</td></tr><tr><td>业务 ID（如订单号）</td><td>视有序程度</td><td>可能较多</td><td>中等</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 自增主键：顺序写入，页不分裂</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- [页1: 1,2,3...100] → [页2: 101,102...200] → ...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- UUID 主键：随机插入，频繁页分裂</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 页1: [1,3a5b...,7f2e...,99]  → 中间插入导致分裂</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 页1&#39;: [1,3a5b...,52c1]  页2: [7f2e...,99] → 浪费空间</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">主键选型建议</p><ol><li><strong>首选自增 BIGINT</strong>：顺序写入无页分裂，二级索引紧凑</li><li><strong>避免 UUID 做主键</strong>：36 字节 + 随机写入 = 页分裂 + 二级索引膨胀</li><li><strong>分布式场景</strong>：雪花算法（Snowflake ID）兼顾有序和分布式唯一</li></ol></div><h2 id="_3-索引类型与使用" tabindex="-1"><a class="header-anchor" href="#_3-索引类型与使用"><span>3. 索引类型与使用</span></a></h2><h3 id="_3-1-联合索引与最左前缀" tabindex="-1"><a class="header-anchor" href="#_3-1-联合索引与最左前缀"><span>3.1 联合索引与最左前缀</span></a></h3><p>联合索引 <code>(a, b, c)</code> 按 a → b → c 顺序组织 B+ 树，遵循<strong>最左前缀法则</strong>。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 联合索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_abc</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> t1 (a, b, c);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 能走索引</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;                    </span><span style="color:#7F848E;font-style:italic;">-- ✅ 匹配 a</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;          </span><span style="color:#7F848E;font-style:italic;">-- ✅ 匹配 a, b</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;</span><span style="color:#7F848E;font-style:italic;">-- ✅ 匹配 a, b, c</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;          </span><span style="color:#7F848E;font-style:italic;">-- ✅ 匹配 a，c 无法用索引</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不能走索引</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;                    </span><span style="color:#7F848E;font-style:italic;">-- ❌ 缺少最左列 a</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;          </span><span style="color:#7F848E;font-style:italic;">-- ❌ 缺少最左列 a</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;                    </span><span style="color:#7F848E;font-style:italic;">-- ❌ 缺少最左列 a</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 范围查询会中断后续列的索引使用</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">; </span><span style="color:#7F848E;font-style:italic;">-- ✅ a, b 用索引，c 无法用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,9),i(d,{code:``}),o[3]||=n(`<h3 id="_3-2-覆盖索引-covering-index" tabindex="-1"><a class="header-anchor" href="#_3-2-覆盖索引-covering-index"><span>3.2 覆盖索引（Covering Index）</span></a></h3><p>当查询所需的所有列都在索引中，无需回表，称为覆盖索引。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 联合索引 idx_name_salary (name, salary)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: Using index  ← 覆盖索引，无需回表</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: NULL  ← 需要回表获取 dept_id, hire_date 等列</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 优化：通过调整联合索引列来覆盖查询</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_name_salary_dept</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> employees (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, salary, dept_id);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#ABB2BF;">, salary, dept_id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: Using index  ← 覆盖索引</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">覆盖索引是性能利器</p><p><code>EXPLAIN</code> 中 <code>Extra</code> 列出现 <code>Using index</code> 表示触发了覆盖索引。减少回表意味着减少大量随机 IO，对于高并发查询场景效果显著。</p></div><h3 id="_3-3-索引下推-index-condition-pushdown-icp" tabindex="-1"><a class="header-anchor" href="#_3-3-索引下推-index-condition-pushdown-icp"><span>3.3 索引下推（Index Condition Pushdown, ICP）</span></a></h3><p>MySQL 5.6 引入的优化，在<strong>存储引擎层</strong>提前过滤，减少回表次数。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 联合索引 (name, salary)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;张%&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 15000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 无 ICP（5.6 之前）：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 存储引擎通过 name LIKE &#39;张%&#39; 找到所有匹配的主键</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 回表获取完整行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. Server 层再过滤 salary &gt; 15000</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 回表次数 = name LIKE &#39;张%&#39; 匹配的行数</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 有 ICP（5.6+）：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 存储引擎通过 name LIKE &#39;张%&#39; 找到匹配记录</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 在索引内直接判断 salary &gt; 15000（下推条件）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 只对同时满足两个条件的记录回表</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 回表次数 = name LIKE &#39;张%&#39; AND salary &gt; 15000 的行数（更少）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,7),i(d,{code:``}),o[4]||=n(`<div class="hint-container important"><p class="hint-container-title">ICP 触发条件</p><ul><li><code>EXPLAIN</code> 中 <code>Extra</code> 列显示 <code>Using index condition</code></li><li>仅适用于二级索引（聚簇索引无回表概念）</li><li>联合索引的最左前缀列用于检索，后续列用于条件过滤</li><li>子查询条件不能下推</li></ul></div><h3 id="_3-4-索引合并-index-merge" tabindex="-1"><a class="header-anchor" href="#_3-4-索引合并-index-merge"><span>3.4 索引合并（Index Merge）</span></a></h3><p>MySQL 可以对同一张表的多个索引合并使用：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 两个单列索引</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_a</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> t1 (a);</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_b</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> t1 (b);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Merge Intersection（交集）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t1 </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 同时用 idx_a 和 idx_b 查找，取交集后回表</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: Using intersect(idx_a,idx_b)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Merge Union（并集）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t1 </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: Using union(idx_a,idx_b)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Index Merge Sort-Union（排序并集）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t1 </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> a </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 各索引范围扫描后排序合并</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Extra: Using sort_union(idx_a,idx_b)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">索引合并不如联合索引</p><p>Index Merge 看似能用多个单列索引，但效果远不如一个精心设计的联合索引。OR 条件尤其危险——如果查询频繁，应建立合适的联合索引代替依赖 Index Merge。</p></div><h2 id="_4-explain-详解" tabindex="-1"><a class="header-anchor" href="#_4-explain-详解"><span>4. EXPLAIN 详解</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">EXPLAIN </span><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dept_name</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees e</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> departments d </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dept_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">id</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">salary</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> 10000</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dept_name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;技术部&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>列</th><th>含义</th><th>关键值</th></tr></thead><tbody><tr><td>id</td><td>查询序号</td><td>子查询/JOIN 越大越先执行</td></tr><tr><td>select_type</td><td>查询类型</td><td>SIMPLE / PRIMARY / SUBQUERY / DERIVED</td></tr><tr><td>table</td><td>访问的表</td><td>衍生表为 <code>&lt;derivedN&gt;</code></td></tr><tr><td>partitions</td><td>匹配的分区</td><td>非分区表为 NULL</td></tr><tr><td><strong>type</strong></td><td><strong>访问类型</strong></td><td><strong>从好到差：</strong> system &gt; const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL</td></tr><tr><td>possible_keys</td><td>可能使用的索引</td><td>NULL 表示无可用索引</td></tr><tr><td>key</td><td>实际使用的索引</td><td>NULL 表示未用索引</td></tr><tr><td>key_len</td><td>使用的索引长度</td><td>判断联合索引用了几列</td></tr><tr><td>ref</td><td>与索引比较的列</td><td>const / 列名</td></tr><tr><td>rows</td><td>预估扫描行数</td><td>越小越好</td></tr><tr><td>filtered</td><td>过滤比例</td><td>100 最佳，10 表示 90% 被丢弃</td></tr><tr><td><strong>Extra</strong></td><td><strong>额外信息</strong></td><td>Using index / Using where / Using filesort / Using temporary</td></tr></tbody></table><h3 id="type-列详解" tabindex="-1"><a class="header-anchor" href="#type-列详解"><span>type 列详解</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- system / const：最多一行匹配</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- type: const（主键/唯一索引等值查询）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- eq_ref：关联查询中，每次匹配一行</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees e </span><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> departments d </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">dept_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">id</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- d 表 type: eq_ref（主键关联）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ref：非唯一索引等值查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- type: ref（dept_id 非唯一）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- range：索引范围扫描</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> salary </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#D19A66;"> 10000</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 20000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- type: range</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- index：全索引扫描</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- type: index（扫描二级索引，比 ALL 好）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ALL：全表扫描</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- type: ALL（最差，必须优化）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="extra-列关键值" tabindex="-1"><a class="header-anchor" href="#extra-列关键值"><span>Extra 列关键值</span></a></h3><table><thead><tr><th>Extra 值</th><th>含义</th><th>优化建议</th></tr></thead><tbody><tr><td>Using index</td><td>覆盖索引</td><td>✅ 最佳</td></tr><tr><td>Using index condition</td><td>索引下推</td><td>✅ 已优化</td></tr><tr><td>Using where</td><td>Server 层过滤</td><td>检查能否下推到索引</td></tr><tr><td>Using filesort</td><td>额外排序</td><td>⚠️ 检查 ORDER BY 是否走索引</td></tr><tr><td>Using temporary</td><td>使用临时表</td><td>❌ 需优化，常见于 GROUP BY + DISTINCT</td></tr></tbody></table><h2 id="_5-索引失效的常见场景" tabindex="-1"><a class="header-anchor" href="#_5-索引失效的常见场景"><span>5. 索引失效的常见场景</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 对索引列使用函数</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#56B6C2;"> YEAR</span><span style="color:#ABB2BF;">(hire_date) </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2023</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 失效，改为：</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> hire_date </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#98C379;"> &#39;2023-01-01&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> hire_date </span><span style="color:#56B6C2;">&lt;</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 隐式类型转换</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;1&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- id 是 BIGINT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 字符串转数字，索引失效（MySQL 将 &#39;1&#39; 转为 1）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 保持类型一致：WHERE id = 1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. LIKE 左模糊</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;%张&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 左模糊无法走 B+ 树</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 右模糊可以：WHERE name LIKE &#39;张%&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 全文索引或搜索引擎解决左模糊需求</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 4. OR 条件中有一方无索引</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 15000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ salary 无索引，整条语句退化为全表扫描</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 为 salary 建索引，或拆为两条 UNION</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 5. 不满足最左前缀</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 联合索引 (a, b, c)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t1 </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> b </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 跳过最左列 a</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 6. NOT IN / NOT EXISTS / != / &lt;&gt;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">!=</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 优化器可能放弃索引，取决于数据分布</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 7. IS NOT NULL（视数据分布）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#C678DD;">IS NOT NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ⚠️ 如果大部分行都不为 NULL，优化器认为全表扫描更快</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">索引失效不等于一定不用索引</p><p>MySQL 优化器会根据统计信息判断。即使索引可用，如果优化器认为全表扫描更快（如数据量小或选择性低），也会放弃索引。关键是看 <code>EXPLAIN</code> 的实际执行计划。</p></div><h2 id="_6-实际索引设计案例" tabindex="-1"><a class="header-anchor" href="#_6-实际索引设计案例"><span>6. 实际索引设计案例</span></a></h2><p>参考 <a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">DBeaver</a> 的数据库管理场景，为通用业务系统设计索引：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 电商订单表索引设计</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> ec_orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id             </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#ABB2BF;">    order_no       </span><span style="color:#C678DD;">VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">32</span><span style="color:#ABB2BF;">)    </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;订单号，如 SN20250115001&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    user_id        </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#C678DD;">         TINYINT</span><span style="color:#C678DD;">        NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> COMMENT </span><span style="color:#98C379;">&#39;0待付 1已付 2已发 3完成 4取消&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    total_amount   </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    created_at     </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)    </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    updated_at     </span><span style="color:#C678DD;">DATETIME</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)    </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">ON UPDATE</span><span style="color:#56B6C2;"> CURRENT_TIMESTAMP</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 唯一索引：订单号</span></span>
<span class="line"><span style="color:#C678DD;">    UNIQUE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#ABB2BF;"> uk_order_no (order_no),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 联合索引：用户查询自己的订单（高频）</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_user_created (user_id, created_at),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 联合索引：后台按状态+时间筛选</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_status_created (</span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 覆盖索引：订单列表页只需部分字段</span></span>
<span class="line"><span style="color:#C678DD;">    INDEX</span><span style="color:#ABB2BF;"> idx_user_status (user_id, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at, total_amount)</span></span>
<span class="line"><span style="color:#ABB2BF;">) ENGINE </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> InnoDB </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#ABB2BF;"> CHARSET </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> utf8mb4;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container important"><p class="hint-container-title">高频考点</p><ol><li><strong>B+ 树 vs B 树</strong>：B+ 树数据只在叶子、叶子有链表、查询路径等长。这是最基础的问题。</li><li><strong>聚簇索引 vs 二级索引</strong>：聚簇索引存完整行、二级索引存主键值需回表。面试必问。</li><li><strong>为什么推荐自增主键</strong>：避免页分裂 + 二级索引紧凑。两个理由都要说。</li><li><strong>最左前缀法则</strong>：联合索引 <code>(a,b,c)</code> 能走哪些查询、不能走哪些查询。面试常给 SQL 判断是否走索引。</li><li><strong>覆盖索引</strong>：<code>Using index</code>，查询列全在索引中无需回表。面试手写 SQL 优化题常用。</li><li><strong>索引下推 ICP</strong>：5.6 引入，存储引擎层提前过滤减少回表。面试加分项。</li><li><strong>索引失效场景</strong>：函数、隐式转换、左模糊、OR 侧无索引、不满足最左前缀。高频考点。</li><li><strong>EXPLAIN 的 type 列</strong>：从好到差排序，至少说出 const/ref/range/index/ALL 的含义。</li></ol></div><div class="hint-container tip"><p class="hint-container-title">参考资源</p><ul><li><a href="https://xiaolincoding.com/mysql/" target="_blank" rel="noopener noreferrer">小林coding - MySQL 索引</a>：图解 B+ 树与索引优化</li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/optimization.html" target="_blank" rel="noopener noreferrer">MySQL 8.0 官方文档 - Optimization</a>：索引优化官方指南</li><li><a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">DBeaver</a>：使用 ER Diagram 功能可视化索引设计</li></ul></div>`,21)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};